<section class="admin-head"><div><p class="kicker">Bespoke Studio</p><h1>Quotes & design approvals</h1><p>Revision-controlled custom work from request through deposit and production design freeze.</p></div></section>
<div class="admin-filter-row"><?php foreach([''=>'All','REQUESTED'=>'Requested','AWAITING_APPROVAL'=>'Awaiting approval','APPROVED_AWAITING_DEPOSIT'=>'Deposit due','DEPOSIT_PAID'=>'Ready to freeze','DESIGN_FROZEN'=>'Frozen'] as $value=>$label):?><a class="<?=($status??'')===$value?'active':''?>" href="<?=e(url('/admin/quotes'.($value?'?status='.rawurlencode($value):'')))?>"><?=e($label)?></a><?php endforeach;?></div>
<section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Quote</th><th>Customer / piece</th><th>Revision</th><th>Status</th><th>Value</th><th>Updated</th></tr></thead><tbody><?php foreach($quotes as $q):$r=bespoke_latest_revision($q);?><tr><td><a href="<?=e(url('/admin/quote/'.$q['guid']))?>"><strong><?=e($q['number'])?></strong></a></td><td><?=e($q['customer_snapshot']['name'])?><small><?=e($q['product_snapshot']['name'])?></small></td><td><?=e((string)($q['current_revision']?:'—'))?></td><td><span class="status-pill bespoke <?=e(strtolower($q['status']))?>"><?=e(bespoke_status_label($q['status']))?></span></td><td><?= $r?money((int)$r['pricing']['total']):'—' ?></td><td><?=e(date('d M H:i',strtotime($q['updated_at'])))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$quotes):?><div class="empty-state"><h2>No bespoke quotes in this view.</h2></div><?php endif;?></section>
